<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$items=json_decode($_POST['cart']??'[]',true);$method=$_POST['method']??'cash';$paid=round((float)($_POST['paid']??0),2);
 if(!is_array($items)||!count($items))$error='Add at least one product to the order.';
 elseif(!in_array($method,['cash','ecocash','zipit','card','other'],true))$error='Choose a valid payment method.';
 else try{$pdo->beginTransaction();$subtotal=0;$validated=[];
  foreach($items as $it){$id=(int)($it['id']??0);$qty=(float)($it['qty']??0);if($qty<=0||$qty>999)throw new Exception('Invalid item quantity.');$st=$pdo->prepare('SELECT * FROM products WHERE id=? AND is_available=1');$st->execute([$id]);$p=$st->fetch();if(!$p)throw new Exception('A selected product is no longer available.');$line=round($qty*(float)$p['price'],2);$subtotal+=$line;$validated[]=['p'=>$p,'qty'=>$qty,'line'=>$line];}
  $total=round($subtotal,2);if($paid+0.0001<$total)throw new Exception('Amount received is less than the total.');
  $shift=$pdo->prepare("SELECT id FROM cash_shifts WHERE cashier_id=? AND status='open' ORDER BY id DESC LIMIT 1");$shift->execute([$_SESSION['user']['id']]);$shiftId=$shift->fetchColumn()?:null;
  $receipt='TMC-'.date('ymd').'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);
  $s=$pdo->prepare('INSERT INTO sales(receipt_number,cashier_id,shift_id,subtotal,total) VALUES(?,?,?,?,?)');$s->execute([$receipt,$_SESSION['user']['id'],$shiftId,$subtotal,$total]);$saleId=$pdo->lastInsertId();
  $si=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)');
  foreach($validated as $v){$si->execute([$saleId,$v['p']['id'],$v['p']['name'],$v['qty'],$v['p']['price'],$v['line']]);
   // Deduct recipe ingredients where the manager has configured a recipe.
   $rs=$pdo->prepare('SELECT ri.stock_item_id,ri.quantity_used FROM recipes r JOIN recipe_items ri ON ri.recipe_id=r.id WHERE r.product_id=? FOR UPDATE');$rs->execute([$v['p']['id']]);foreach($rs->fetchAll() as $ri){$deduct=$v['qty']*$ri['quantity_used'];$up=$pdo->prepare('UPDATE stock_items SET quantity_on_hand=quantity_on_hand-? WHERE id=? AND quantity_on_hand>=?');$up->execute([$deduct,$ri['stock_item_id'],$deduct]);if(!$up->rowCount())throw new Exception('Insufficient ingredient stock to complete this sale.');$mv=$pdo->prepare("INSERT INTO stock_movements(stock_item_id,user_id,movement_type,quantity_change,note) VALUES(?,?,'sale',?,?)");$mv->execute([$ri['stock_item_id'],$_SESSION['user']['id'],-$deduct,'Sale '.$receipt]);}
  }
  $pay=$pdo->prepare('INSERT INTO payments(sale_id,method,amount,reference) VALUES(?,?,?,?)');$pay->execute([$saleId,$method,$total,trim($_POST['reference']??'')]);
  $pdo->commit();log_action('Sale completed',$receipt.' total '.$total);header('Location: receipt.php?id='.$saleId);exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}
}
$products=$pdo->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_available=1 ORDER BY c.name,p.name')->fetchAll();$cats=$pdo->query('SELECT name FROM categories WHERE is_active=1 ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='New Sale / POS';require 'includes/header.php';?>
<?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?>
<div class="pos-layout"><div class="menu-area"><div class="pos-heading"><div><h1>New order</h1><p class="muted">Choose products to add them to the order.</p></div><input id="productSearch" class="search-input" placeholder="⌕ Search menu..."></div><div class="category-tabs"><button class="cat-tab active" data-category="all">All items</button><?php foreach($cats as $c):?><button class="cat-tab" data-category="<?=e($c)?>"><?=e($c)?></button><?php endforeach;?></div><div class="product-grid" id="productGrid"><?php foreach($products as $p):?><button type="button" class="product-tile" data-id="<?=$p['id']?>" data-name="<?=e($p['name'])?>" data-price="<?=$p['price']?>" data-category="<?=e($p['category'])?>"><span class="product-placeholder">🍽</span><b><?=e($p['name'])?></b><small><?=e($p['category'])?></small><strong><?=money($p['price'])?></strong></button><?php endforeach;?></div></div>
<aside class="order-panel"><div class="order-title"><h2>Current order</h2><button type="button" class="link-button" id="clearCart">Clear</button></div><div id="cartItems" class="cart-items"><div class="empty">Select menu items to begin.</div></div><div class="order-bottom"><div class="total-line"><span>Subtotal</span><b id="subtotal">$0.00</b></div><div class="total-line grand"><span>Total due</span><strong id="total">$0.00</strong></div><form method="post" id="checkoutForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="cart" id="cartJson"><label>Payment method</label><select name="method" id="paymentMethod"><option value="cash">Cash</option><option value="ecocash">EcoCash</option><option value="zipit">ZIPIT</option><option value="card">Card</option><option value="other">Other</option></select><label>Amount received (USD)</label><input type="number" min="0" step="0.01" name="paid" id="paidAmount" placeholder="0.00" required><div class="change-line"><span>Change</span><b id="changeAmount">$0.00</b></div><input name="reference" placeholder="Payment reference (optional)"><button class="btn primary full" type="submit" id="completeSale" disabled>Complete sale & print receipt</button></form></div></aside></div>
<script>window.TMC_PRODUCTS=<?=json_encode(array_map(fn($p)=>['id'=>(int)$p['id'],'name'=>$p['name'],'price'=>(float)$p['price'],'category'=>$p['category']],$products),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;</script>
<?php require 'includes/footer.php';?>
